rows=[]
def add(id,title,authors,year,venue,url,read,mechanism,transfer,boundary,versions=None,implementation=None,tier='core'):
    rows.append(dict(id=id,title=title,authors=authors,year=year,venue=venue,primary_url=url,source_level='primary author-hosted text and/or publisher metadata',identity_verification='verified',reading_scope=read,main_classification=mechanism,problem='Active localization/search from uncertain sensor observations',transfer_to_task=transfer,limitations=boundary,versions=versions or [],implementation=implementation or 'not yet implemented',tier=tier,awards='not investigated; no award claim',code_url=None,data_url=None))
trio=['Joshua Vander Hook','Pratap Tokekar','Volkan Isler']
add('IROS2011','Active Target Localization for Bearing Based Robotic Telemetry',['Pratap Tokekar','Joshua Vander Hook','Volkan Isler'],2011,'IROS 2011','https://josh.vanderhook.info/media/pdf/iros2011localization.pdf','PDF pp.1–4: context, initialization, open-loop/greedy/min-max tree; experiments not yet fully read','online planning / measurement-outcome tree','Adaptive observation branches; charge motion plus each measurement.','Gaussian/EKF and 180-degree ambiguity; fixed grid/action discretization and hypothetical future bearings differ from this task.',versions=[{'doi':'10.1109/IROS.2011.6048778','date':'2011-09'}],implementation='Existing sampled active-measurement planners overlap; bounded two-step planning remains under study.')
add('ICRA2012','Cautious Greedy Strategy for Bearing-based Active Localization: Experiments and Theoretical Analysis',trio,2012,'ICRA 2012','https://josh.vanderhook.info/media/pdf/icra2012bot.pdf','PDF pp.1–4: problem, EKF, beta-caution constraint, algorithm; detailed proof deferred by paper to technical report','local geometry / cautious approach','Choose perpendicular-to-major-uncertainty views and account for measurement cost.','Probabilistic backward ambiguity/EKF bound is not a deterministic source-containment theorem; no direct 20 m clearing guarantee.',versions=[{'doi':'10.1109/ICRA.2012.6225244','date':'2012-05'}],implementation='Not transplanted: task already has oriented bearings with bounded error; local geometry family existed before this stage.')
add('ICRA2013','Sensor Placement and Selection for Bearing Sensors with Bounded Uncertainty',['Pratap Tokekar','Volkan Isler'],2013,'ICRA 2013','https://doi.org/10.1109/ICRA.2013.6630920','Identity verified from publisher-deposited metadata and author publication list. Author PDF link returns 404; university repository copy encountered HTML challenge; full text still being recovered.','set geometry / bounded-error sensor selection','Relevant to worst-case region width and observation-set selection; detailed theorem not attributed without full text.','No paper-specific guarantee or algorithm adopted while source text remains inaccessible.',implementation='R3 convex no-signal exclusion is our own derivation, not claimed as this paper algorithm.',tier='identity_only')
add('ISER2013','Local-Search Strategy for Active Localization of Multiple Invasive Fish',trio[:2]+['Elliot Branson','Przemyslaw G. Bajer','Peter W. Sorensen','Volkan Isler'],2013,'Experimental Robotics, STAR 88, pp.859–873','https://josh.vanderhook.info/media/pdf/iser2013init.pdf','PDF pp.1–15 read: problem, failed initialization alternatives, four-ray/single/multi-target search, cost analysis, simulations, field deployment, limitations, references.','discovery and initialization / shared local-search cost','Reuse already visited target neighborhoods to initialize other undetected channels; all extra measurements charged.','Four-ray circle fitting needs isotropic receive circles/aggregation and cheap detection; Q4 is directional and measures cost 5–6 seconds.',versions=[{'doi':'10.1007/978-3-319-00065-7_57','publication_year':2013,'note':'2013 is book publication year; conference-event year not independently established here.'}],implementation='E3 R1 paid unknown-channel initialization implemented: small development gain, full4800 Q4 +0.2605% slower, rejected.')
add('JFR2014','Cautious Greedy Strategy for Bearing-only Active Localization: Analysis and Field Experiments',trio,2014,'Journal of Field Robotics 31(2), 296–318','https://josh.vanderhook.info/media/pdf/JoshV_JFR_2013_Localization.pdf','PDF pp.1–3 and 6–8 read: identity/version, assumptions, closest-approach ellipse, Algorithm 1, initialization and guarantee statement; full appendices not read.','local geometry / cautious approach','Uncertainty-adaptive approach distance; decouple initialization, active sensing and complete coverage.','Expected constant-factor claims depend on paper assumptions, not inherited by ±1-degree hulls or deterministic local noise fields.',versions=[{'doi':'10.1002/rob.21499','online_date':'2014-01-28','print_date':'2014-03','note':'Received/accepted in 2013 and filename says 2013, but published in 2014; extends ICRA2012 and local-search work.'}],implementation='Source clarification and mechanism family; no separate algorithm counted from conference predecessor.')
add('TRO2015','Algorithms for Cooperative Active Localization of Static Targets With Mobile Bearing Sensors Under Communication Constraints',trio,2015,'IEEE Transactions on Robotics 31(4), 864–876','https://josh.vanderhook.info/media/pdf/tro2015cooploc.pdf','PDF pp.1–2 and 8–9 read: cost/CRLB model and MULTI-STEP online conversion. Offline algorithms and full proof not independently rederived.','online planning / conservative-region multi-step conversion','Plan from a conservative region and revisit belief after observations; closest feasible location prevents committing to an unreliable distant centroid.','Communication/rendezvous and parallel robots do not exist here; CRLB, independent Gaussian updates and log-factor result are not task guarantees.',versions=[{'doi':'10.1109/TRO.2015.2432612','date':'2015-08'}],implementation='R3 uses reliable set geometry but convex negative rule is independently derived; full MULTI-STEP not yet reproduced.')
add('ISRR2015_family','Detecting, Localizing, and Tracking an Unknown Number of Moving Targets Using a Team of Mobile Robots',['Philip Dames','Pratap Tokekar','Vijay Kumar'],2015,'ISRR 2015; book chapter 2017; extended IJRR 2017/2018','https://raaslab.org/pubs/dames2017detecting.pdf','Author 2015 conference listing verified. Downloaded file is IJRR 2017 manuscript, pp.1–2 read; full conference version link 404. Also downloaded 2018 journal version, not counted as a new method.','discovery and tracking / random-finite-set intensity','Separate expected detection count from conditional localization accuracy; explore undetected mass without declaring source absence.','Unknown data association, target births/deaths, mobile targets and false positives are absent in task; a low posterior existence weight cannot certify channel absence.',versions=[{'venue':'ISRR','event_year':2015,'identity_source':'https://raaslab.org/publications.html'},{'doi':'10.1007/978-3-319-51532-8_31','publication_date':'2017-07-27'},{'doi':'10.1177/0278364917709507','online_date':'2017-06-05','note':'Journal extension; 2018 issue version exists.'}],implementation='Unknown-channel R1 probes expected discovery benefit directly; no PHD filter implemented.')
add('ATL2020','Active Localization of Multiple Targets from Noisy Relative Measurements',['Selim Engin','Volkan Isler'],2020,'WAFR 2020; Algorithmic Foundations of Robotics XIV book 2021','https://ksengin.github.io/papers/wafr2020active.pdf','PDF pp.1–16 read: assumptions, histogram, TD3, image and multimodal states/rewards, offline-Fisher comparison, static/dynamic/generalization experiments and references.','online planning / learned multi-target belief policy','Joint belief representation can value a route beyond immediate single-target shrinkage.','All targets initially observable; per-step observations from all targets; Gaussian noise; finite horizon and estimation error rather than paid-channel complete clearing. Multimodal reward uses true positions in training; only image reward avoids them.',versions=[{'doi':'10.1007/978-3-030-66723-8_24','publication_date':'2021-02-09','title_correction':'from, not using'}],implementation='E3 R2 finite cross-target side-score is an existing mechanism re-evaluated on S1, not ATL/TD3 replication; all three weights negative on development.')
add('CDC2016','Non-Myopic Target Tracking Strategies for Non-Linear Systems',['Zhongshun Zhang','Pratap Tokekar'],2016,'IEEE Conference on Decision and Control, 5591–5596','https://raaslab.org/pubs/zhang2016nonmyopic.pdf','PDF pp.1–3 read: nonlinear observation dependence, finite outcome/action minimax tree, alpha pruning, algebraic redundancy statement.','online planning / robust outcome tree and pruning','Use observed-outcome branches rather than a single imagined bearing; bound computation with fixed small branch set.','Gaussian EKF and covariance monotonicity/pruning assumptions differ from bounded polygon loss of signal; cannot reuse pruning guarantees without proof.',versions=[{'doi':'10.1109/CDC.2016.7799128','year':2016}],implementation='Candidate finite robust lookahead still under study; not claimed implemented.',tier='extension')
add('ICRA2017_FOV','Algorithm for Searching and Tracking an Unknown and Varying Number of Mobile Targets using a Limited FoV Sensor',['Yoonchang Sung','Pratap Tokekar'],2017,'ICRA 2017, 6246–6252','https://raaslab.org/pubs/sung2017algorithm.pdf','PDF pp.1–2 read: assumptions, search/tracking split and GM-PHD equations.','discovery and tracking / limited-FoV birth and track management','Maintain discovered and not-yet-observed hypotheses separately; missed observations are not nonexistence.','Requires mobile anonymous targets, Gaussian position observations, false-positive process and survival/birth models. Static known-channel task has no birth/death or data association.',versions=[{'doi':'10.1109/ICRA.2017.7989740','date':'2017-05'}],implementation='Not implemented; central machinery has no task counterpart.',tier='extension')
